import{_ as e,c as p,o as r,af as t}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"爻位第十一","description":"杭氏易學 - 爻位第十一","frontmatter":{"title":"爻位第十一","description":"杭氏易學 - 爻位第十一"},"headers":[],"relativePath":"classics/hangshi/012.md","filePath":"classics/hangshi/012.md"}'),s={name:"classics/hangshi/012.md"};function i(n,a,l,c,h,o){return r(),p("div",null,[...a[0]||(a[0]=[t('<h1 id="爻位第十一" tabindex="-1">爻位第十一 <a class="header-anchor" href="#爻位第十一" aria-label="Permalink to “爻位第十一”">​</a></h1><p>六位六虛</p><h3 id="六位" tabindex="-1">六位 <a class="header-anchor" href="#六位" aria-label="Permalink to “六位”">​</a></h3><p>分陰分陽，迭用柔剛，故《易》六位而成章。六位者，初爻二爻為地位，三爻四爻為人位，五爻上爻為天位。以乾卦例之，初九在地之下，故曰“潛”。九二地之上，故曰“田”。三爻為人之正位，故曰“君子”。四爻不當位，故曰“或”。五爻天位，故曰“在天”。上九在天之上，故曰“亢也”。</p><p>位有一定，而爻則變動無常。學者必先知有定之位，定其為陰為陽，為上為下，而後爻之奇偶當否，可得而言也 【偶居陰，奇居陽，為當，反之為不當】 。</p><p>分陰分陽，迭用柔剛。惟既濟一卦，為陰陽柔剛各當其位，故曰“既濟定也”。定則不動，不動則不生，而《易》道或幾乎息矣。故荀虞均以乾坤成兩既濟為兇。《序卦》曰：“《易》不可窮也，故受之以未濟終也。”此以陰陽之位言之也。若以用言，則一卦六爻，惟中四爻得用。初未用事，而上則失位。故《乾?上》曰：“高而無位”，《需?上》日“位不當也”。王弼曰“上下無位”者，指此也。</p><h3 id="六虛" tabindex="-1">六虛 <a class="header-anchor" href="#六虛" aria-label="Permalink to “六虛”">​</a></h3><p>《系傳》曰：“上下無常，周流六虛。”六虛者，即初二三四五上之位也。爻實位虛，爻有上下，而位無變動。爻有柔剛，位有陰陽 【一三五為陽，二四六為陰】 ，剛柔雜居 【剛居陽，柔居陰，為當。或以剛居陰，柔居陽，則相雜而文生焉】 ，吉凶以著。《參同契》曰：“二用無爻位，周流行六虛。”二用者即九與六也。乾九坤六，上下升降，周流六虛，以成六十四卦。故觀象者不可僅觀所見之六爻。六爻之下，尚有六虛，皆與此所見之六爻相關。爻為飛，位為伏，實易辨而虛難知。必由實而究其虛，庶遇爻而知其用，於《易》之道思過半矣。</p><h3 id="八卦正位" tabindex="-1">八卦正位 <a class="header-anchor" href="#八卦正位" aria-label="Permalink to “八卦正位”">​</a></h3><p>爻位六而卦有八，八卦於六爻，各有其當位之爻，曰正位。家人曰“男正位乎外，女正位乎內”，言九五與六二，則但以陰陽言也。陰陽以二五爻為得中得正，乾坤為卦之宗主，亦陰陽之純體。故乾以九五為正位，坤以六二為正位，坎離為乾坤之交 【坎中之陽即乾爻，離中之陰即坤爻】 。故坎離之正位，與乾坤同。震以初九為正位，艮以九三為正位，巽以六四為正位，兌以上六為正位。卦各有其正位，故六爻具六子之位。為圖如下：</p><p>端木氏曰：天地六爻，坎離既濟定位，五多功二多譽，位當也。離坎未濟居方，三多兇四多懼，不當位也。有當位而不正者，而正位未有不當者也。而《彖》、《象》之言正則以二五，故八卦惟乾坤坎離之為得中得正也。</p><p>六爻三極定位，天地定位。六爻上山澤，下雷風，中水火。六爻三極，下二初地爻地極，雷風恆，天地下極立心恆，坤地極立不易方，二初震巽爻是也，五上天爻天極，山澤損天上極員 【損從員】 ，乾天恆無方，中日月鬥，三人行，乾極與時偕行，五上艮兌爻是也。四三人爻人極，水火既濟，天地中間人，於天地上下初終，首尾續終，中為人極。兼三才而兩之，定上下中極，四三坎離爻是也。六爻三極，天地南北居方，六爻辨物辨等。乾坤六十四卦終下坎北極，故曰“初難知”，曰“亦不知極也”。此《易》居方上下六爻三極之道也。</p><p>右圖與前圖合觀，則知爻位之隱見變化，不但卦有飛伏交互，而爻之飛伏交互，亦與卦等也。向之說《易》家，能究心於爻位之義者甚鮮，而於爻位之分，更未有言之者。來知德氏，雖有八卦之正位一圖，而注中仍不能用，則以未明爻位之體用有別也。今合二圖而一之，並附以說，庶閱者可瞭然矣。</p><p>六十四卦三百八十四爻，皆乾坤二用，周流六虛，至既濟而全卦之爻位相當。故曰“既濟定也”。</p><p>爻位既明，二用斯章。然乾元用九，綱領全《易》。地道無成，坤之用皆乾之用也。乾無方無體，乾之用皆見於坤之用也。孔子《文言傳》曾發乾九用坤，坤六承乾之旨，已極詳備。大明終始，六位時成，乃非既濟而為未濟，其故可深長思矣。</p><p>乾六位，火本天親上。離五位，水本地親下。坎二位，而上下剛柔應位。山澤，艮上位兌三位。雷風，震四位巽初位。而上下六位，巽伏，震起，兌見，艮止，皆中離坎日月象。故曰“大明終始六位時成 【下巽伏，上兌見，即坎象。下震起，上艮止，即離象。】 。”《上經》始乾坤終坎離，其往來卦十八。《下經》始鹹恆終既未濟，其往來卦十八。十八為二九數，乃離坎二卦日月終始。離一九，寅數止戌。坎一九，申數正辰。此離坎二九，皆乾用九圓，日月為大明象。乾二九十八卦，《上經》始乾坤，終坎離，大明終始六位是也。離坎二卦，南北終始，皆出入於震兌二卦，東西往來。震一九亥數止未，兌一九巳數止醜。此震一九離出震，兌一九坎出兌，皆乾用九圓。而上、下《經》各往來卦十八，始乾終既未濟，乾六位成而坤天下平。此離坎上下六位，南北居方卦大明日月也。上下卦十八終始三十六，是為乾四九出入，南北上下為之極。其卦三十六，皆離坎首尾終之始之。而乾坤上下六十四卦六位，皆此離坎六位終始之。是乾用九乾圓象，而六十四卦以成終成始，乾大明終始，六位時成是也。</p><p>六爻二極，尤重在人。天地之氣，以人而通。陰陽之道，以人而和。孔子贊《易》“立人之道”，以合乎天地之正。《京氏易傳》：孔子曰“陽三陰四，位之正也”，三者東方之數，日之所出也。四者西方之數，日之所入也。言日月終天之道。故《易》卦六十四，分上下象陰陽也。故奇偶之數取之於乾坤。乾坤者，陰陽之根本也。陰陽之道備著於坎離。坎離者，陰陽之性命也，而其樞要皆在於三四兩爻。於此求之，六十四卦之辭義可迎刃而解矣。圖附後。</p><p>天地人六爻往復，天地上下，在人中爻三四迴轉。而上下天地爻，乃往復不窮。此乾坤六爻上下應位，二三四五同功異位，皆具此六爻往復中，皆在中人爻迴轉。人於天地上下，不見首尾，乃中間背脊，其道反覆不已。天地往復，其道不窮。孔子六十四卦大象，著六十四“以”字。“以”，古文作 ，即結合上下兩卦往復迴轉之象也。</p>',18)])])}const f=e(s,[["render",i]]);export{_ as __pageData,f as default};
